-- Hosbah: the short-lived, one-time handoff for a desktop browser. Opening a desktop browser from
-- the web app mints one of these (the plaintext token is never stored — token_hash is its SHA-256)
-- and sends the member to https://<browser hostname>/.hosbah/auth?token=..., which forward_auth lets
-- through unauthenticated (see internal/server/authorization.go). That endpoint looks the row up by
-- hash, checks it is unused and unexpired, marks it used_at (a token is exchanged exactly once —
-- replay is refused), and sets a host-only, HttpOnly, Secure, SameSite=Lax cookie scoped to that
-- exact browser hostname (the session cookie itself is host-only on the app's own domain, so it does
-- not reach a browser subdomain). Rows are pruned lazily: expired or used rows are harmless, never
-- re-checked.
ALTER TABLE browser_auth_tokens ADD CONSTRAINT browser_auth_tokens_expiry_check CHECK (expires_at > created_at);
CREATE UNIQUE INDEX browser_auth_tokens_token_hash_key ON browser_auth_tokens (token_hash);
CREATE INDEX browser_auth_tokens_browser_idx ON browser_auth_tokens (browser_id);
CREATE INDEX browser_auth_tokens_expires_idx ON browser_auth_tokens (expires_at);
